html:
{%- set settings = frappe.get_cached_doc("NeoAqua Settings") -%}
{%- set company = frappe.get_cached_doc("Company", doc.company) -%}
<div class="na-receipt">
  <div class="na-c na-brand">{{ company.company_name }}</div>
  <div class="na-c na-ar">مصنع نيو أكوا للمياه</div>
  <div class="na-c na-sm">
    {% if company.tax_id %}VAT / الرقم الضريبي: {{ company.tax_id }}<br>{% endif %}
    {% if settings.sfda_licence_no %}SFDA: {{ settings.sfda_licence_no }}<br>{% endif %}
    {% if company.phone_no %}{{ company.phone_no }}{% endif %}
  </div>

  <div class="na-c na-title">
    {% if doc.is_return %}CREDIT NOTE / إشعار دائن
    {% else %}SIMPLIFIED TAX INVOICE<br>فاتورة ضريبية مبسطة{% endif %}
  </div>

  <div class="na-rule"></div>

  <table class="na-meta">
    <tr><td>Invoice</td><td class="na-r">{{ doc.name }}</td></tr>
    <tr><td>Date / التاريخ</td><td class="na-r">{{ frappe.utils.format_datetime(doc.posting_date ~ " " ~ doc.posting_time, "dd-MM-yyyy HH:mm") }}</td></tr>
    <tr><td>Customer / العميل</td><td class="na-r">{{ doc.customer_name }}</td></tr>
    {% if doc.get("neoaqua_van") %}<tr><td>Van / المركبة</td><td class="na-r">{{ doc.neoaqua_van }}</td></tr>{% endif %}
    {% if doc.get("neoaqua_salesman") %}<tr><td>Salesman</td><td class="na-r">{{ doc.neoaqua_salesman }}</td></tr>{% endif %}
    {% if doc.get("neoaqua_sale_type") %}<tr><td>Type</td><td class="na-r">{{ doc.neoaqua_sale_type }}</td></tr>{% endif %}
  </table>

  <div class="na-rule"></div>

  <table class="na-items">
    <thead>
      <tr><th class="na-l">Item</th><th class="na-r">Qty</th><th class="na-r">Rate</th><th class="na-r">Amount</th></tr>
    </thead>
    <tbody>
      {% for row in doc.items %}
      <tr class="na-item-name"><td colspan="4">{{ row.item_name }}</td></tr>
      <tr>
        <td class="na-l na-sm">{{ row.item_code }}</td>
        <td class="na-r">{{ row.qty | round(2) }}</td>
        <td class="na-r">{{ "%.2f" | format(row.rate) }}</td>
        <td class="na-r">{{ "%.2f" | format(row.amount) }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>

  <div class="na-rule"></div>

  <table class="na-tot">
    <tr><td>Total excl. VAT / الإجمالي</td><td class="na-r">{{ "%.2f" | format(doc.net_total) }}</td></tr>
    {% for t in doc.taxes %}
    <tr><td>{{ t.description }}</td><td class="na-r">{{ "%.2f" | format(t.tax_amount) }}</td></tr>
    {% endfor %}
    <tr class="na-grand">
      <td>TOTAL / الإجمالي شامل</td>
      <td class="na-r">{{ "%.2f" | format(doc.rounded_total or doc.grand_total) }} SAR</td>
    </tr>
    {% if doc.paid_amount %}
    <tr><td>Paid / المدفوع</td><td class="na-r">{{ "%.2f" | format(doc.paid_amount) }}</td></tr>
    {% endif %}
    {% if doc.outstanding_amount > 0 %}
    <tr class="na-due">
      <td>BALANCE DUE / المتبقي</td>
      <td class="na-r">{{ "%.2f" | format(doc.outstanding_amount) }}</td>
    </tr>
    {% endif %}
  </table>

  {% if doc.get("neoaqua_containers_out") or doc.get("neoaqua_empties_collected") %}
  <div class="na-rule"></div>
  <table class="na-tot">
    <tr><td>Containers delivered</td><td class="na-r">{{ doc.neoaqua_containers_out or 0 }}</td></tr>
    <tr><td>Empties collected</td><td class="na-r">{{ doc.neoaqua_empties_collected or 0 }}</td></tr>
  </table>
  {% endif %}

  {% if doc.get("ksa_einv_qr") %}
  <div class="na-c na-qr"><img src="{{ doc.ksa_einv_qr }}" style="width:120px;height:120px"></div>
  {% endif %}

  <div class="na-rule"></div>
  <div class="na-c na-sm">
    Goods received in good condition<br>
    استلمت البضاعة بحالة جيدة<br><br>
    <div class="na-sign">Customer signature / توقيع العميل</div>
  </div>
  <div class="na-c na-sm na-foot">Thank you &middot; شكراً لتعاملكم معنا</div>
</div>

<style>
  @media print { @page { margin: 0; } body { margin: 0; } }
  .na-receipt { width: 72mm; margin: 0 auto; font-family: "Segoe UI", Tahoma, sans-serif;
                font-size: 11px; color: #000; line-height: 1.35; }
  .na-c { text-align: center; } .na-l { text-align: left; } .na-r { text-align: right; }
  .na-brand { font-size: 17px; font-weight: 700; letter-spacing: .5px; margin-top: 4px; }
  .na-ar { font-size: 13px; margin-bottom: 3px; }
  .na-sm { font-size: 10px; }
  .na-title { font-weight: 700; font-size: 12px; margin: 6px 0 4px; }
  .na-rule { border-top: 1px dashed #000; margin: 5px 0; }
  .na-meta, .na-items, .na-tot { width: 100%; border-collapse: collapse; }
  .na-meta td { padding: 1px 0; font-size: 10px; }
  .na-items th { border-bottom: 1px solid #000; padding: 2px 0; font-size: 10px; }
  .na-items td { padding: 0 0 3px; font-size: 10px; }
  .na-item-name td { padding-top: 3px; font-weight: 600; font-size: 11px; }
  .na-tot td { padding: 1px 0; font-size: 11px; }
  .na-grand td { border-top: 1px solid #000; padding-top: 3px; font-weight: 700; font-size: 13px; }
  .na-due td { font-weight: 700; }
  .na-qr { margin: 8px 0 4px; }
  .na-sign { margin-top: 26px; border-top: 1px solid #000; padding-top: 2px; }
  .na-foot { margin-top: 6px; }
</style>
